from typing import List
from step import SagaStep
from context import SagaContext

class SagaCoordinator:
    def __init__(self, context: SagaContext):
        self.steps: List[SagaStep] = []
        self.completed_steps: List[SagaStep] = []
        self.context = context

    def add_step(self, step: SagaStep) -> None:
        self.steps.append(step)

    def execute(self) -> bool:
        self.completed_steps = []
        for step in self.steps:
            try:
                step.action(self.context.data)
                self.context.record(step.name, "action")
                self.completed_steps.append(step)
            except Exception as e:
                self.context.record(step.name, "failed")
                self._rollback()
                return False
        return True

    def _rollback(self) -> None:
        # Bug: executes compensation in forward order (FIFO) instead of reverse (LIFO)
        for step in self.completed_steps:
            step.compensate(self.context.data)
            self.context.record(step.name, "compensate")

